from taf.sbts.oam.sc.rest.schemas.base import SchemaField, SchemaObject


class UnitAvailableOperationSlotSMV1(SchemaObject):
    name = SchemaField(name="name", not_null=True)
    label = SchemaField(name="label", not_null=True)
    description = SchemaField(name="description", not_null=True)
    state = SchemaField(name="state", not_null=True)
    impacted_uids = SchemaField(name="impacted_uids", optional=True)

    def __init__(self, name=None, label=None, description=None, state=None, impacted_uids=None):
        self.name = name
        self.label = label
        self.description = description
        self.state = state
        self.impacted_uids = impacted_uids

        super(UnitAvailableOperationSlotSMV1, self).__init__()


class UnitAvailableOperationsSMV1(SchemaObject):
    operations = SchemaField(name="operations", klass=UnitAvailableOperationSlotSMV1, many=True, not_null=True)

    def __init__(self, operations=None):
        self.operations = operations

        super(UnitAvailableOperationsSMV1, self).__init__()
